<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Dezerx; use Illuminate\Http\JsonResponse; use Pterodactyl\Http\Requests\Api\Client\ClientApiRequest; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; class PreferencesController extends ClientApiController { private const MAX_CATEGORIES = 24; private const MAX_SERVERS = 200; private const COLOURS = ['accent', 'blue', 'green', 'amber', 'red', 'purple', 'pink', 'teal']; public function index(ClientApiRequest $request): JsonResponse { return new JsonResponse(['categories' => $this->categories($request)]); } public function update(ClientApiRequest $request): JsonResponse { $data = $request->validate([ 'categories' => ['present', 'array', 'max:' . self::MAX_CATEGORIES], 'categories.*.id' => ['required', 'string', 'max:64'], 'categories.*.name' => ['required', 'string', 'max:40'], 'categories.*.icon' => ['sometimes', 'nullable', 'string', 'max:32'], 'categories.*.colour' => ['sometimes', 'nullable', 'string', 'max:16'], 'categories.*.servers' => ['present', 'array', 'max:' . self::MAX_SERVERS], 'categories.*.servers.*' => ['string', 'max:64'], ]); $categories = []; $seen = []; foreach ($data['categories'] as $category) { if (in_array($category['id'], $seen, true)) { continue; } $seen[] = $category['id']; $categories[] = [ 'id' => $category['id'], 'name' => trim($category['name']), 'icon' => $category['icon'] ?? null, 'colour' => $this->colour($category['colour'] ?? null), 'servers' => array_values(array_unique($category['servers'])), ]; } $user = $request->user(); $user->forceFill([ 'dezerx_preferences' => [...($user->dezerx_preferences ?? []), 'serverCategories' => $categories], ])->saveOrFail(); return new JsonResponse(['categories' => $categories]); } private function colour(?string $value): ?string { $value = mb_strtolower(trim((string) $value)); return in_array($value, self::COLOURS, true) ? $value : null; } private function categories(ClientApiRequest $request): array { $stored = $request->user()->dezerx_preferences['serverCategories'] ?? []; return is_array($stored) ? array_values($stored) : []; } } 